// Des: Tests the AI adapter chain and its daily cap
// Flo: off = refuses > Claude CLI missing falls back to the llama.cpp mock > cap stops extra calls > non-loopback url refused > JSON content parsed
// I/O: mock llama server on loopback + missing exe name (no real AI, no network) > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-smar-adap-test.zig
// ===================================================================
const std = @import("std"); const adap = @import("ru-smar-adap.zig"); const task = @import("ru-task-runn.zig"); const mockm = @import("te-mock-page.zig"); const stat = @import("st-stat-main.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Env = struct { tmpz: std.testing.TmpDir, dbp: [:0]u8, sto: stat.Stat, aren: std.heap.ArenaAllocator, page: pg.Page, rng: pace.Rng, sinkl: std.ArrayList(u8),
fn up(self: *Env) !void { self.sinkl = .empty; self.tmpz = std.testing.tmpDir(.{}); self.dbp = try std.fmt.allocPrintSentinel(allo, ".zig-cache/tmp/{s}/fb.db", .{self.tmpz.sub_path}, 0); self.sto = try stat.Stat.open(allo, self.dbp); self.aren = std.heap.ArenaAllocator.init(allo); self.rng = pace.Rng.init(1); }
fn down(self: *Env) void { self.aren.deinit(); self.sto.close(); allo.free(self.dbp); self.tmpz.cleanup(); }
fn ctx(self: *Env, conf: cfgz.Conf) task.Ctx { return .{ .gpaz = allo, .aren = self.aren.allocator(), .iozz = std.testing.io, .conf = conf, .store = &self.sto, .mode = .dry, .page = &self.page, .rng = &self.rng, .base = "", .sink = &self.sinkl }; } };
test "url split allows only loopback http with a port" { const sp = try adap.urlSplit("http://127.0.0.1:8080"); try std.testing.expectEqual(@as(u16, 8080), sp.port); _ = try adap.urlSplit("http://localhost:9/x"); try std.testing.expectError(error.AiFail, adap.urlSplit("http://example.com:80")); try std.testing.expectError(error.AiFail, adap.urlSplit("https://127.0.0.1:8080")); try std.testing.expectError(error.AiFail, adap.urlSplit("http://127.0.0.1")); }
test "content parse trims, refuses empty and bad json" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectEqualStrings("hi there", try adap.contentOf(aren.allocator(), "{\"content\":\"  hi there \\n\"}")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "{\"content\":\"  \"}")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "nope")); try std.testing.expectError(error.AiFail, adap.contentOf(aren.allocator(), "{\"x\":1}")); }
test "switch off refuses; missing Claude falls back to llama.cpp mock" { var mock: mockm.Mock = undefined; try mock.start(std.testing.io); defer mock.halt(); var env: Env = undefined; try env.up(); defer env.down(); var conf: cfgz.Conf = .{}; var cx = env.ctx(conf); try std.testing.expectError(error.AiFail, adap.draftChain(&cx, "hello")); conf.smar_mode_enab = true; conf.smar_clau_exec = "zz-no-such-claude-exe"; conf.smar_llam_urlz = try std.fmt.allocPrint(env.aren.allocator(), "http://127.0.0.1:{d}", .{mock.port}); cx = env.ctx(conf); try std.testing.expectEqualStrings("Sure, happy to help!", try adap.draftChain(&cx, "hello")); }
test "daily AI cap: calls past the cap are refused so templates take over" { var mock: mockm.Mock = undefined; try mock.start(std.testing.io); defer mock.halt(); var env: Env = undefined; try env.up(); defer env.down(); var conf: cfgz.Conf = .{}; conf.smar_mode_enab = true; conf.smar_call_dayz = 2; conf.smar_clau_exec = "zz-no-such-claude-exe"; conf.smar_llam_urlz = try std.fmt.allocPrint(env.aren.allocator(), "http://127.0.0.1:{d}", .{mock.port}); var cx = env.ctx(conf); _ = try adap.draftChain(&cx, "one"); _ = try adap.draftChain(&cx, "two"); try std.testing.expectError(error.AiFail, adap.draftChain(&cx, "three")); try std.testing.expectEqual(@as(i64, 2), try env.sto.actCnt("ai", 0)); cx.now_fix = task.nowMs(&cx) + 3 * 86400000; _ = try adap.draftChain(&cx, "next day"); }
test "every tool failing gives AiFail and costs no cap" { var env: Env = undefined; try env.up(); defer env.down(); var conf: cfgz.Conf = .{}; conf.smar_mode_enab = true; conf.smar_clau_exec = "zz-no-such-claude-exe"; conf.smar_llam_urlz = "http://127.0.0.1:1"; var cx = env.ctx(conf); try std.testing.expectError(error.AiFail, adap.draftChain(&cx, "hello")); try std.testing.expectEqual(@as(i64, 0), try env.sto.actCnt("ai", 0)); }
